class ATMException(Exception):
    """Base exception for ATM operations"""
    pass


class InvalidPINException(ATMException):
    """Exception raised when PIN is incorrect"""
    pass


class InsufficientBalanceException(ATMException):
    """Exception raised when balance is insufficient for withdrawal"""
    pass


def main():
    # Read PIN and withdrawal amount from input
    pin = int(input().strip())
    withdrawal_amount = int(input().strip())

    # Initialize ATM with correct PIN and balance
    CORRECT_PIN = 1234
    balance = 5000  # Initial balance

    try:
        # Check if PIN is valid
        if pin != CORRECT_PIN:
            raise InvalidPINException()

        # Check if balance is sufficient
        if withdrawal_amount > balance:
            raise InsufficientBalanceException()

        # Process withdrawal
        balance -= withdrawal_amount
        print(balance)

    except InvalidPINException:
        print("Invalid PIN!")
    except InsufficientBalanceException:
        print("Insufficient balance!")


if __name__ == "__main__":
    main()
